import {PROGRAM,PHASES} from './program.js';
import {APP_ID,STORE_KEY,OBJECTIVES,uid,today,fresh,importState,mergeStates,normalizeRecord,stats,qualification,timerSeconds,sessionPlan,csv,noteName,makeQuestion} from './core.mjs';
import {playNotes,stopAudio} from './audio.mjs';

const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes={dashboard:['Vue d’ensemble','Ta pratique en un regard'],program:['Mon parcours','Les 36 paliers'],session:['Séance guidée','Écouter, chanter, vérifier'],workshop:['Atelier d’écoute','Modèles sonores et clavier'],history:['Mes séances','Historique et séances libres'],journal:['Journal','Réussites et points à reprendre'],vocabulary:['Mes motifs','Un vocabulaire sonore personnel'],keys:['Tonalités','Repères et transposition'],assessment:['Bilans','Tes cinq objectifs'],resources:['Méthode & ressources','Programme, sources, EarMaster'],data:['Sauvegardes','Données et préférences']};
const statusLabels={todo:'À découvrir',doing:'En cours',repeat:'À consolider',done:'Validé'};
let state=fresh(),storageError=false;
try{const raw=localStorage.getItem(STORE_KEY);if(raw)state=importState(JSON.parse(raw));const saved=raw?JSON.parse(raw):null;if(saved?.timer)state.timer=saved.timer}catch{storageError=true}
let route=Object.hasOwn(routes,location.hash.slice(1))?location.hash.slice(1):'dashboard';
let selectedStage=state.profile.currentStage,selectedSlot='0',filters={query:'',phase:'all',status:'all'},historySearch='',historyKind='all',question=null,questionAnswered=false,replays=0,workResults=[],keyboardInput=[],timerNotice=false;
const stageOf=id=>({...PROGRAM.find(p=>p.id===Number(id)),...state.stageOverrides[id]});
const phaseOf=id=>PHASES.find(p=>p.id===Number(id));
const fmtDate=d=>d?new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00')):'Non datée';
const doneRecords=id=>state.records.filter(r=>r.done&&(id===undefined||r.stage===Number(id)));
const statusOf=id=>state.stageStatus[id]||(doneRecords(id).length?'doing':'todo');
const stageOptions=current=>PROGRAM.map(p=>`<option value="${p.id}" ${p.id===Number(current)?'selected':''}>${p.id}. ${esc(stageOf(p.id).title)}</option>`).join('');
const btn=(action,label,extra='',cls='btn-secondary')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const pill=(label,cls='')=>`<span class="pill ${cls}">${esc(label)}</span>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function save(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(STORE_KEY,JSON.stringify(state));storageError=false}catch{storageError=true;toast('Sauvegarde locale indisponible. Exporte tes données avant de fermer.')}updateSide()}
function updateSide(){const n=stats(state).validated;$('#sidePercent').textContent=Math.round(n/36*100)+' %';$('#sideCount').textContent=`${n} / 36 paliers validés`;$('#sideMeter').style.width=(n/36*100)+'%';document.documentElement.dataset.theme=state.profile.theme}
function go(next){route=Object.hasOwn(routes,next)?next:'dashboard';history.replaceState(null,'','#'+route);$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
function openDialog(title,body){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#dialog').showModal()}
function closeDialog(){$('#dialog').close()}
function head(kicker,title,desc='',action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`}
function empty(text){return `<div class="empty">${text}</div>`}
function kpi(label,value,note=''){return `<article class="card kpi"><div><div class="label">${label}</div><div class="value">${value}</div><div class="small muted">${note}</div></div></article>`}
function phaseCards(){return PHASES.map(p=>{const n=PROGRAM.filter(s=>s.phase===p.id&&statusOf(s.id)==='done').length,total=p.end-p.start+1;return `<button class="phase-overview" style="--phase-color:${p.color}" data-action="phase-filter" data-id="${p.id}"><span class="phase-index">0${p.id}</span><div><strong>${p.title}</strong><small>Paliers ${p.start} à ${p.end} · ${n}/${total} validés</small><div class="meter"><span style="width:${n/total*100}%"></span></div></div><span aria-hidden="true">↗</span></button>`}).join('')}
function dashboard(){const s=stats(state),p=stageOf(state.profile.currentStage),q=qualification(state,p.id),weekly=Math.min(100,s.weekSessions/state.profile.weeklyTarget*100);return `${head('Piano · oreille · imagination','Le son commence en toi.',`${esc(state.profile.name)}, un petit espace quotidien pour entendre plus précisément et jouer avec intention.`)}
<section class="ear-hero"><div class="hero-copy"><span class="eyebrow">Ton prochain rendez-vous avec la musique</span><h3>${esc(p.title)}</h3><p>${esc(p.focus)}<br>Palier ${String(p.id).padStart(2,'0')} sur 36 · ${state.profile.defaultDuration} minutes à ton rythme</p><div class="hero-actions">${btn('start-current','Reprendre ma séance <span aria-hidden="true">→</span>','','btn-gold')}${btn('stage-detail','Voir le palier',`data-id="${p.id}"`)}</div></div><div class="sound-art" aria-hidden="true"><div class="sound-orbit"></div><div class="wave">${[20,36,58,85,55,116,76,143,105,65,92,48,67,30,16].map((v,i)=>`<i style="height:${v}px;--i:${i}"></i>`).join('')}</div><span>écouter &nbsp;·&nbsp; imaginer &nbsp;·&nbsp; jouer</span></div></section>
<section class="grid grid-4 dashboard-kpis">${kpi('Paliers validés',s.validated+' <small>/ 36</small>','Une progression par acquis')}${kpi('Séances terminées',s.sessions,'Guidées, optionnelles et libres')}${kpi('Temps de pratique',s.minutes<60?s.minutes+' <small>min</small>':(s.minutes/60).toLocaleString('fr-FR',{maximumFractionDigits:1})+' <small>h</small>',s.minutes+' minutes cumulées')}${kpi('Cette semaine',s.weekSessions+' <small>/ '+state.profile.weeklyTarget+'</small>',s.weekMinutes+' minutes depuis lundi')}</section>
<div class="grid grid-2"><article class="card"><div class="eyebrow">Ton rythme</div><h3>Un peu, régulièrement</h3><div class="metric-row"><span>${s.days} jours de pratique</span><span>${Math.round(s.average)} min par séance en moyenne</span></div><div class="meter" style="margin:16px 0"><span style="width:${weekly}%"></span></div><p class="small">Ton repère : ${state.profile.weeklyTarget} séances par semaine. Les jours supplémentaires peuvent rester des jours de révision.</p>${btn('free-session','+ Séance libre')}</article><article class="card"><div class="eyebrow">Palier actuel</div><h3>Des acquis qui se confirment</h3><div class="criterion-steps">${[1,2,3].map(n=>`<span class="criterion-dot ${q.days>=n?'ok':''}">${q.days>=n?'✓':n}</span>`).join('')}<span class="small">${Math.min(3,q.days)}/3 jours de réussite</span></div><p class="small">${q.sessions}/5 séances minimum · essais nouveaux et première réponse à 80 %${q.rhythmRequired?' en hauteurs et en rythme':''}.</p>${btn('stage-detail',q.ready?'Examiner la validation':'Voir les critères',`data-id="${p.id}"`)}</article></div>
<div class="section-title"><div><h3>Ton chemin d’écoute</h3><p>Sept phases, une difficulté nouvelle à la fois.</p></div>${btn('route','Tout le parcours','data-route="program"')}</div><div class="phase-overviews">${phaseCards()}</div>
<div class="section-title"><h3>Les dernières séances</h3>${btn('route','Tout l’historique','data-route="history"')}</div>${recordList(doneRecords().slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3))}`}

function program(){const list=PROGRAM.map(p=>stageOf(p.id)).filter(p=>(!filters.query||[p.title,p.focus,p.exercise,p.criterion].join(' ').toLowerCase().includes(filters.query.toLowerCase()))&&(filters.phase==='all'||p.phase===Number(filters.phase))&&(filters.status==='all'||statusOf(p.id)===filters.status));return `${head('Une progression par acquis','Les 36 paliers','Chaque palier comprend cinq séances essentielles. Tu peux répéter, ajouter une révision et éditer le contenu.')}
<div class="filters"><div class="search"><input id="programSearch" aria-label="Rechercher un palier" placeholder="Chercher un objectif, un son, une notion…" value="${esc(filters.query)}"></div><select id="phaseFilter" aria-label="Filtrer par phase"><option value="all">Toutes les phases</option>${PHASES.map(p=>`<option value="${p.id}" ${String(p.id)===filters.phase?'selected':''}>${p.id}. ${p.title}</option>`).join('')}</select><select id="statusFilter" aria-label="Filtrer par statut"><option value="all">Tous les statuts</option>${Object.entries(statusLabels).map(([v,l])=>`<option value="${v}" ${v===filters.status?'selected':''}>${l}</option>`).join('')}</select></div><div class="small muted" style="margin-bottom:14px">${list.length} paliers affichés</div>
<div class="week-grid">${list.map(p=>{const ph=phaseOf(p.phase),q=qualification(state,p.id);return `<article class="card week-card" style="--phase-color:${ph.color}"><div class="week-number">Phase ${p.phase} · Palier ${String(p.id).padStart(2,'0')}</div><h3>${esc(p.title)}</h3><p>${esc(p.focus)}</p><div class="metric-row"><span>${q.sessions} séances</span><span>${Math.min(3,q.days)}/3 jours de réussite</span></div><div class="meter" style="margin:10px 0 15px"><span style="width:${statusOf(p.id)==='done'?100:Math.min(85,(q.sessions/5*40)+(q.days/3*45))}%"></span></div><div class="week-footer">${pill(statusLabels[statusOf(p.id)],statusOf(p.id)==='done'?'green':statusOf(p.id)==='repeat'?'gold':'')}${btn('stage-detail','Ouvrir',`data-id="${p.id}"`,'btn-secondary btn-sm')}</div></article>`}).join('')||empty('Aucun palier ne correspond aux filtres.')}</div>`}

function stageDetail(id){const p=stageOf(id),q=qualification(state,p.id),note=state.stageNotes[id]||'';openDialog(`Palier ${p.id} · ${p.title}`,`<div class="eyebrow">${esc(phaseOf(p.phase).title)}</div><p class="lead">${esc(p.focus)}</p><div class="detail-box"><h3>Le travail précis</h3><p>${esc(p.exercise)}</p></div><div class="detail-box"><h3>Vérifier et poursuivre</h3><p>${esc(p.criterion)}</p></div><div class="detail-box"><h3>Ta progression</h3><p>${q.sessions} séances réalisées · ${q.days} jours distincts de réussite · reprise différée ${q.delayed?'présente':'à confirmer'}.</p><p class="small">Repère : 5 séances minimum et 3 jours distincts à au moins 80 % sur des essais nouveaux en première réponse${q.rhythmRequired?', avec hauteurs et rythme stables':''}. Les problèmes de détection technique sont exclus.</p>${q.ready?pill('Critères chiffrés réunis','green'):pill('À confirmer par la pratique','gold')}</div>
<form data-form="stage-status" data-id="${p.id}"><div class="editor-grid"><label class="field">Statut<select name="status">${Object.entries(statusLabels).map(([v,l])=>`<option value="${v}" ${statusOf(id)===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Note sur cet acquis<textarea name="notes">${esc(note)}</textarea></label></div><p class="small muted">La validation reste ta décision. Si tu la renseignes manuellement, conserve ici le constat qui la justifie.</p><div class="detail-actions">${btn('select-stage','Travailler ce palier',`data-id="${p.id}"`,'btn-primary')}${btn('edit-stage','Éditer le contenu',`data-id="${p.id}"`)}<button class="btn btn-secondary" type="submit">Enregistrer le suivi</button></div></form>`)}
function editStage(id){const p=stageOf(id);openDialog('Éditer le palier '+id,`<form data-form="edit-stage" data-id="${id}"><div class="editor-grid">${field('title','Titre',p.title)}${field('focus','Objectif précis',p.focus)}${area('exercise','Exercice et progression',p.exercise,'span-2')}${area('criterion','Critères et simplification',p.criterion,'span-2')}${area('transfer','Transfert musical',p.transfer,'span-2')}</div><div class="detail-actions"><button type="submit" class="btn btn-primary">Enregistrer les modifications</button>${btn('reset-stage','Restaurer ce palier',`data-id="${id}"`)}</div></form>`)}
function field(name,label,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function area(name,label,value='',cls=''){return `<label class="field ${cls}">${label}<textarea name="${name}">${esc(value)}</textarea></label>`}
function planFor(stage,slot){return slot.startsWith('extra:')?state.extraPlans.find(p=>p.id===slot.slice(6)):sessionPlan(stage,Number(slot),state)}
function recordsForSlot(stage,slot){return doneRecords(stage).filter(r=>r.slot===String(slot))}
function session(){const p=stageOf(selectedStage),plan=planFor(selectedStage,selectedSlot)||sessionPlan(selectedStage,0,state);return `${head('Un rendez-vous de 10 à 15 minutes','Ma séance guidée','Une intention précise, des modèles courts, puis un retour sur ce qui a changé.',btn('free-session','+ Séance libre'))}
<div class="filters"><label class="field grow">Palier<select id="guidedStage">${stageOptions(selectedStage)}</select></label><label class="field grow">Séance<select id="guidedSlot">${Array.from({length:5},(_,i)=>`<option value="${i}" ${selectedSlot===String(i)?'selected':''}>${String.fromCharCode(65+i)} · ${esc(sessionPlan(selectedStage,i,state).title)}</option>`).join('')}${state.extraPlans.filter(x=>x.stage===selectedStage).map(x=>`<option value="extra:${esc(x.id)}" ${selectedSlot==='extra:'+x.id?'selected':''}>Optionnelle · ${esc(x.title)}</option>`).join('')}</select></label></div>
<div class="session-focus card"><div><div class="eyebrow">Palier ${p.id} · ${esc(p.title)}</div><h3>${esc(plan.title)}</h3><p>${esc(plan.objective)}</p><div class="detail-actions">${btn('record-plan','Consigner la séance','','btn-primary')}${btn('edit-plan','Éditer cette séance')}${btn('add-plan','+ Séance optionnelle')}</div></div><div class="timer-panel"><div class="eyebrow">Mon temps de pratique</div><strong class="timer-clock" id="timerClock">00:00</strong><span class="small" id="timerContext"></span><div class="detail-actions">${btn('timer-toggle','Démarrer','id="timerToggle"','btn-navy')}${btn('timer-reset','Remettre à zéro')}</div></div></div>
<div class="grid grid-2 session-body"><article class="card"><div class="eyebrow">Le cœur du travail</div><h3>${esc(p.focus)}</h3><p>${esc(p.exercise)}</p>${plan.instructions?`<div class="notice">${esc(plan.instructions)}</div>`:''}<div class="detail-actions">${btn('workshop-stage','Ouvrir l’atelier sonore',`data-id="${p.id}"`,'btn-primary')}${btn('stage-detail','Critères du palier',`data-id="${p.id}"`)}</div><p class="small muted">L’atelier propose un support de travail. Pour les sous-étapes plus avancées du palier, suivre les consignes ci-dessus avec le piano ou EarMaster.</p></article><article class="card"><div class="eyebrow">${plan.duration} minutes, sans se presser</div><h3>Le déroulé</h3>${sessionSteps(plan.duration).map(x=>`<div class="session-step"><span>${x[0]} min</span><div><strong>${x[1]}</strong><p>${x[2]}</p></div></div>`).join('')}</article></div>
<article class="notice"><strong>Vérifier et simplifier.</strong> ${esc(p.criterion)}<br><strong>Transfert.</strong> ${esc(p.transfer)}</article>
<div class="section-title"><h3>Les séances du palier</h3></div><div class="session-list">${Array.from({length:5},(_,i)=>{const pl=sessionPlan(selectedStage,i,state),rs=recordsForSlot(selectedStage,String(i));return `<article class="session-card ${rs.length?'done':''}"><span class="session-letter">${rs.length?'✓':String.fromCharCode(65+i)}</span><div><h4>${esc(pl.title)}</h4><p>${pl.duration} min · ${pl.optional?'optionnelle':'essentielle'} · ${rs.length} réalisation${rs.length>1?'s':''}</p></div><div class="session-actions">${btn('choose-slot','Ouvrir',`data-slot="${i}"`,'btn-secondary btn-sm')}</div></article>`}).join('')}${state.extraPlans.filter(p=>p.stage===selectedStage).map(pl=>`<article class="session-card"><span class="session-letter">+</span><div><h4>${esc(pl.title)}</h4><p>${pl.duration} min · optionnelle</p></div><div class="session-actions">${btn('choose-slot','Ouvrir',`data-slot="extra:${esc(pl.id)}"`,'btn-secondary btn-sm')}${btn('delete-plan','Supprimer',`data-id="${esc(pl.id)}"`,'btn-secondary btn-sm')}</div></article>`).join('')}</div>`}
function sessionSteps(duration){const blocks=duration<12?[1,4,2,2,1]:[2,4,3,2,1];const names=['Réactiver','Écouter et reproduire','Localiser et corriger','Transférer','Garder une trace'],texts=['Reprendre un motif déjà réussi et le poursuivre intérieurement.','Travailler seulement la difficulté du palier, en petites séries.','Comparer la réponse au modèle ; isoler le premier écart.','Réutiliser un motif maîtrisé dans une petite cellule musicale.','Noter résultat, aide, confiance et point à reprendre.'];const result=blocks.map((n,i)=>[n,names[i],texts[i]]);const extra=duration-blocks.reduce((a,b)=>a+b,0);if(extra>0)result.splice(4,0,[extra,'Réviser','Reprendre un acquis familier, sans nouvelle difficulté.']);return result}
function editPlan(isNew=false){const plan=isNew?{title:'Révision personnelle',duration:12,objective:'Consolider un acquis du palier.',instructions:'',optional:true}:planFor(selectedStage,selectedSlot);openDialog(isNew?'Ajouter une séance optionnelle':'Éditer la séance',`<form data-form="plan" data-new="${isNew}"><div class="editor-grid">${field('title','Titre',plan.title)}${field('duration','Durée prévue (10 à 15 min)',plan.duration,'number','min="10" max="15" required')}${area('objective','Objectif',plan.objective,'span-2')}${area('instructions','Consignes personnelles',plan.instructions,'span-2')}<label class="check"><input type="checkbox" name="optional" ${plan.optional?'checked':''}>Séance optionnelle</label></div><div class="detail-actions"><button type="submit" class="btn btn-primary">Enregistrer</button></div></form>`)}

function recordForm(existing=null,free=false){const pl=planFor(selectedStage,selectedSlot)||sessionPlan(selectedStage,0,state),t=state.timer,elapsed=t&&t.stage===selectedStage&&t.slot===selectedSlot?timerSeconds(t):0;const r=existing||{id:'',stage:selectedStage,slot:free?'free':selectedSlot,title:free?'Séance libre':pl.title,date:today(),minutes:elapsed?Math.max(1,Math.round(elapsed/60)):pl.duration,kind:free?'free':selectedSlot.startsWith('extra:')?'extra':'guided',trials:10,pitch:'',rhythm:'',assisted:'',confidence:'hesitant',difficulty:3,key:'',notes:'',win:'',novel:false,technical:false,done:true};
openDialog(existing?'Modifier une séance':free?'Ajouter une séance libre':'Consigner ma séance',`<form data-form="record" data-id="${esc(r.id)}" data-slot="${esc(r.slot)}" data-kind="${r.kind}"><div class="editor-grid">${field('title','Titre',r.title,'text','required')}<label class="field">Palier<select name="stage">${stageOptions(r.stage)}</select></label>${field('date','Date',r.date,'date','required')}${field('minutes','Minutes réellement travaillées',r.minutes,'number','min="0" max="1440" step="0.5" required')}<label class="field">Difficulté ressentie<select name="difficulty">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===Number(r.difficulty)?'selected':''}>${n}/5</option>`).join('')}</select></label><label class="field">Confiance<select name="confidence">${[['sure','Sûr'],['hesitant','Hésitant'],['guess','Deviné']].map(([v,l])=>`<option value="${v}" ${r.confidence===v?'selected':''}>${l}</option>`).join('')}</select></label>${field('trials','Nombre d’essais',r.trials,'number','min="1" max="1000" required')}${field('pitch','Hauteurs correctes en première réponse',r.pitch??'','number','min="0" max="1000"')}${field('rhythm','Rythmes corrects en première réponse',r.rhythm??'','number','min="0" max="1000"')}${field('assisted','Réussites après aide / réécoute',r.assisted??'','number','min="0" max="1000"')}${field('key','Tonalité ou notes travaillées',r.key)}<label class="check"><input type="checkbox" name="novel" ${r.novel?'checked':''}>Essais nouveaux, score de première réponse</label><label class="check"><input type="checkbox" name="technical" ${r.technical?'checked':''}>Détection ou retour technique douteux</label><label class="check"><input type="checkbox" name="done" ${r.done?'checked':''}>Séance terminée</label>${area('win','Ce qui a réussi',r.win,'span-2')}${area('notes','Erreur localisée / point à reprendre',r.notes,'span-2')}</div><p class="small muted">Laisse les scores vides si tu n’as pas évalué ces dimensions. Une séance terminée compte une fois dans les séances et dans les minutes.</p><div class="detail-actions"><button class="btn btn-primary" type="submit">Enregistrer la séance</button></div></form>`)}
function recordList(records){return records.length?`<div class="history-list">${records.map(r=>`<article class="entry"><div class="entry-date">${esc(fmtDate(r.date))}<br>${r.minutes} min</div><div><div class="eyebrow">Palier ${r.stage} · ${r.kind==='free'?'Libre':r.kind==='extra'?'Optionnelle':'Guidée'}${r.done?'':' · À terminer'}</div><h4>${esc(r.title)}</h4><p>${r.pitch!==null?'Hauteurs '+r.pitch+'/'+r.trials+' · ':''}${r.rhythm!==null?'Rythme '+r.rhythm+'/'+r.trials+' · ':''}${r.technical?'Retour technique à vérifier':r.novel?'Première réponse, matériau nouveau':'Entraînement'}</p>${r.win?`<p><strong>Réussite :</strong> ${esc(r.win)}</p>`:''}${r.notes?`<p>${esc(r.notes)}</p>`:''}</div><div class="entry-actions">${btn('edit-record','Éditer',`data-id="${esc(r.id)}"`,'btn-secondary btn-sm')}${btn('delete-record','Supprimer',`data-id="${esc(r.id)}"`,'btn-secondary btn-sm')}</div></article>`).join('')}</div>`:empty('Aucune séance pour le moment. Une première séance, et la pratique prend forme.')}
function historyPage(){const list=state.records.filter(r=>(historyKind==='all'||r.kind===historyKind)&&[r.title,r.notes,r.win,r.key,String(r.stage)].join(' ').toLowerCase().includes(historySearch.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return `${head('Chaque séance a sa place','Mon historique','Les séances libres et optionnelles s’ajoutent au même compteur, sans double comptage.',btn('free-session','+ Séance libre'))}<div class="filters"><input id="historySearch" aria-label="Rechercher une séance" placeholder="Titre, note, tonalité, palier…" value="${esc(historySearch)}"><select id="historyKind" aria-label="Type de séance">${[['all','Toutes les séances'],['guided','Guidées'],['extra','Optionnelles'],['free','Libres']].map(([v,l])=>`<option value="${v}" ${v===historyKind?'selected':''}>${l}</option>`).join('')}</select>${btn('export-csv','Exporter en CSV')}</div><p class="small muted">${list.length} séances affichées · ${list.filter(r=>r.done).reduce((s,r)=>s+r.minutes,0)} minutes réalisées</p>${recordList(list)}`}

function journal(){return `${head('Une mémoire de ta pratique','Mon journal','Conserver ce que tu as perçu, compris et retrouvé.',btn('edit-journal','+ Une note'))}<div class="journal-list">${state.journal.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(j=>`<article class="entry"><div class="entry-date">${esc(fmtDate(j.date))}<br>Palier ${j.stage}</div><div><h3>${esc(j.title)}</h3><p>${esc(j.text)}</p></div><div class="entry-actions">${btn('edit-journal','Éditer',`data-id="${esc(j.id)}"`,'btn-secondary btn-sm')}${btn('delete-journal','Supprimer',`data-id="${esc(j.id)}"`,'btn-secondary btn-sm')}</div></article>`).join('')||empty('Une note de journal peut être très courte : une réussite et un point à reprendre.')}</div><p class="small muted">Les minutes de pratique sont consignées dans « Mes séances ». Les notes du journal ne créent pas de séance supplémentaire.</p>`}
function editJournal(id){const j=state.journal.find(x=>x.id===id)||{id:'',title:'',text:'',date:today(),stage:state.profile.currentStage};openDialog(j.id?'Modifier une note':'Une note de pratique',`<form data-form="journal" data-id="${esc(j.id)}"><div class="editor-grid">${field('title','Titre',j.title,'text','required')}${field('date','Date',j.date,'date','required')}<label class="field">Palier<select name="stage">${stageOptions(j.stage)}</select></label>${area('text','Ce que je veux garder',j.text,'span-2')}</div><div class="detail-actions"><button type="submit" class="btn btn-primary">Enregistrer</button></div></form>`)}
function vocabulary(){return `${head('Ce qui devient familier','Mes motifs sonores','Garder des cellules courtes que tu peux entendre, chanter et réutiliser.',btn('edit-vocab','+ Ajouter un motif'))}<div class="week-grid">${state.vocabulary.map(v=>`<article class="card"><div class="eyebrow">${esc(v.type||'Motif')} · ${esc(v.key||'Do')}</div><h3>${esc(v.title)}</h3><p class="motif-notes">${esc(v.notes)}</p><p>${esc(v.comment)}</p>${pill(['À découvrir','En cours','Réutilisable'][Number(v.level)]||'À découvrir')}<div class="detail-actions">${btn('play-vocab','Écouter',`data-id="${esc(v.id)}"`,'btn-primary btn-sm')}${btn('edit-vocab','Éditer',`data-id="${esc(v.id)}"`,'btn-secondary btn-sm')}${btn('delete-vocab','Supprimer',`data-id="${esc(v.id)}"`,'btn-secondary btn-sm')}</div></article>`).join('')||empty('Ajoute une première cellule de deux ou trois notes déjà facile à entendre.')}</div>`}
function editVocab(id){const v=state.vocabulary.find(x=>x.id===id)||{id:'',title:'',type:'Mélodique',key:'Do',notes:'Do Ré Do',comment:'',level:0,date:today()};openDialog(v.id?'Modifier le motif':'Ajouter un motif',`<form data-form="vocab" data-id="${esc(v.id)}"><div class="editor-grid">${field('title','Titre',v.title,'text','required')}${field('type','Type',v.type)}${field('key','Tonalité',v.key)}<label class="field">Niveau<select name="level">${['À découvrir','En cours','Réutilisable'].map((s,i)=>`<option value="${i}" ${Number(v.level)===i?'selected':''}>${s}</option>`).join('')}</select></label>${field('notes','Notes à écouter, séparées par des espaces',v.notes)}${area('comment','Usage / repère personnel',v.comment,'span-2')}</div><p class="small muted">Lecture sonore : Do Ré Mi Fa Sol La Si, avec # ou b si besoin (ex. Sib, Fa#). Les durées restent égales.</p><div class="detail-actions"><button type="submit" class="btn btn-primary">Enregistrer</button></div></form>`)}
const KEYS=['Do','Sol','Ré','La','Mi','Si','Fa♯','Ré♭','La♭','Mi♭','Si♭','Fa'];
function keys(){return `${head('Des repères qui se déplacent','Mes tonalités','Évaluer séparément l’écoute en majeur et en mineur. La seconde tonalité est introduite au palier 22.')}<div class="key-grid">${KEYS.map(k=>{const r=state.keys[k]||{};return `<article class="card key-card"><h3>${k}</h3><div class="key-levels"><div><span class="small muted">Majeur</span><p>${['Non évalué','Découverte','Fonctionnel','Stable'][Number(r.major)||0]}</p></div><div><span class="small muted">Mineur</span><p>${['Non évalué','Découverte','Fonctionnel','Stable'][Number(r.minor)||0]}</p></div></div><p class="small muted">${r.date?fmtDate(r.date):'Pas encore travaillé'}</p><p class="small">${esc(r.notes||'')}</p>${btn('edit-key','Dater et modifier',`data-key="${k}"`,'btn-secondary btn-sm')}</article>`}).join('')}</div>`}
function editKey(k){const r=state.keys[k]||{major:0,minor:0,date:today(),notes:''};openDialog('Écoute en '+k,`<form data-form="key" data-key="${k}"><div class="editor-grid">${['major','minor'].map((n,i)=>`<label class="field">${i?'Mineur':'Majeur'}<select name="${n}">${['Non évalué','Découverte','Fonctionnel','Stable'].map((s,j)=>`<option value="${j}" ${Number(r[n])===j?'selected':''}>${s}</option>`).join('')}</select></label>`).join('')}${field('date','Date du travail',r.date,'date')}${area('notes','Ce qui est stable / à reprendre',r.notes,'span-2')}</div><div class="detail-actions"><button type="submit" class="btn btn-primary">Enregistrer</button></div></form>`)}

function assessment(){const last=state.assessments.at(-1);return `${head('Tes cinq objectifs, dans leur ordre','Un bilan qui suit les acquis','Évalue chaque capacité sur du matériau nouveau de difficulté comparable.')}<div class="grid grid-2"><form class="card" data-form="assessment">${OBJECTIVES.map((o,i)=>`<label class="assessment-row"><span>${i+1}. ${o}</span><select name="score${i}">${['À explorer','Avec aide','Autonome sur du simple','Stable et réutilisable'].map((s,j)=>`<option value="${j}" ${Number(last?.scores?.[i]??0)===j?'selected':''}>${s}</option>`).join('')}</select></label>`).join('')}${area('comment','Constat / prochaine priorité','')}<div class="detail-actions"><button class="btn btn-primary" type="submit">Garder ce bilan daté</button></div></form><article class="card"><div class="eyebrow">Dernier bilan</div><h3>${last?fmtDate(last.date):'Ton point de départ'}</h3>${OBJECTIVES.map((o,i)=>`<div class="assessment-bar"><span>${i+1}. ${o}</span><div class="meter"><span style="width:${(Number(last?.scores?.[i])||0)/3*100}%"></span></div></div>`).join('')}<p class="small muted">Une autoévaluation descriptive : elle complète les essais et ne remplace pas leur vérification.</p></article></div><div class="section-title"><h3>Les bilans précédents</h3></div>${state.assessments.slice().reverse().map(a=>`<article class="entry"><div class="entry-date">${fmtDate(a.date)}</div><div><h4>${a.scores.map(n=>n+'/3').join(' · ')}</h4><p>${esc(a.comment)}</p></div>${btn('delete-assessment','Supprimer',`data-id="${esc(a.id)}"`,'btn-secondary btn-sm')}</article>`).join('')||empty('Enregistre un premier bilan, puis compare après quelques paliers.')}`}

function resources(){return `${head('Une méthode, des repères','Entendre, puis vérifier','Une adaptation personnelle des principes de Gordon et Kodály, en complément de tes autres parcours.')}<div class="grid grid-2"><article class="card"><div class="eyebrow">Le programme de référence</div><h3>36 paliers, à ton rythme</h3><p>Objectifs, progression, critères de passage et consignes détaillées sont accessibles dans les fiches du parcours. Le PDF personnalisé est conservé dans la version OpenAI privée.</p><button class="btn btn-primary" data-action="route" data-route="program">Ouvrir les 36 paliers →</button></article><article class="card"><div class="eyebrow">Un appui pour progresser</div><h3>Partir d’une mélodie familière</h3><p>Écouter une phrase connue, la poursuivre intérieurement et la vérifier sert de point d’appui pour aborder ensuite des modèles nouveaux.</p><p class="small">La note de départ est fournie. Chante dans une octave confortable, avec une émission modérée.</p></article></div><div class="section-title"><h3>Utiliser EarMaster sur iPad</h3></div><article class="card"><p><strong>1. Vérifier le retour.</strong> Tester trois sons tenus dans une zone vocale confortable. Si la courbe est incohérente, régler l’entrée et l’étendue vocale avant d’utiliser le score.</p><p><strong>2. Isoler le retard.</strong> Comparer avec un casque filaire et sans Bluetooth. Rechercher l’aide sur « Input Timing offset » dans ta version ; aucune valeur unique n’est présumée.</p><p><strong>3. Choisir une seule difficulté.</strong> Imitation très courte, puis lecture chantée ; accords et progressions seulement quand leurs sons sont familiers.</p><p><strong>4. Séparer les dimensions.</strong> Une dictée écrite, une reproduction frappée et un chant n’évaluent pas exactement la même tâche. Noter à part les problèmes techniques.</p></article><div class="section-title"><h3>Les sources pédagogiques</h3></div><div class="grid grid-2">${[['GIML · Audiation','https://giml.org/mlt/audiation/','Entendre et comprendre une musique intérieurement.'],['GIML · Progression des apprentissages','https://giml.org/mlt/skilllearningsequence/','Écoute et chant, repères verbaux, puis association à l’écriture.'],['Kodály · OAKE','https://www.oake.org/the-kodaly-concept/','Le chant, le solfège relatif et une progression séquentielle.'],['EarMaster · Activités','https://www.earmaster.com/fr/?catid=8&id=23:earmaster-activites&view=article','Imitation, lecture chantée, rythme, accords et progressions.']].map(([n,u,t])=>`<article class="card"><h3>${n}</h3><p>${t}</p><a href="${esc(u)}" target="_blank" rel="noopener" class="small">Consulter la source ↗</a></article>`).join('')}</div><p class="small muted">Les exercices, les 36 paliers et le seuil de 80 % sont une proposition personnalisée. Sources consultées le 7 novembre 2026.</p>`}

function dataPage(){return `${head('Conserver le chemin parcouru','Sauvegardes & préférences','Une sauvegarde complète emporte tes séances, tes éditions, ton journal et tes bilans.')}<div class="grid grid-2"><article class="card"><h3>Exporter mes données</h3><p>Le JSON permet de restaurer le parcours sur un autre navigateur ou sur l’autre version de l’application.</p><div class="detail-actions">${btn('export','Sauvegarde complète JSON','','btn-primary')}${btn('export-csv','Séances en CSV')}</div><p class="small muted">Les données sont enregistrées dans ce navigateur. Les versions OpenAI et GitHub ont chacune leur sauvegarde locale ; le transfert passe par le JSON.</p></article><article class="card"><h3>Importer une sauvegarde</h3><p>Une fusion ajoute les données et reconnaît les identifiants déjà présents. Un remplacement restaure l’ensemble du fichier.</p><label class="field">Fichier JSON<input id="importFile" type="file" accept="application/json,.json"></label><label class="field" style="margin-top:10px">Méthode<select id="importMode"><option value="merge">Fusionner avec mes données</option><option value="replace">Remplacer mes données</option></select></label><div class="detail-actions">${btn('import','Importer le fichier','','btn-primary')}</div></article></div>
<div class="section-title"><h3>Mon rythme de travail</h3></div><form class="card" data-form="settings"><div class="editor-grid">${field('name','Prénom',state.profile.name)}${field('weeklyTarget','Séances par semaine',state.profile.weeklyTarget,'number','min="1" max="7" required')}${field('defaultDuration','Durée habituelle (10 à 15 min)',state.profile.defaultDuration,'number','min="10" max="15" required')}${field('startDate','Date de début',state.profile.startDate,'date')}${field('tempo','Tempo des modèles sonores',state.profile.tempo,'number','min="40" max="120" required')}<label class="field">Registre des modèles<select name="root">${[[36,'Do grave (Do2)'],[48,'Do médium grave (Do3)'],[60,'Do médium (Do4)']].map(([n,l])=>`<option value="${n}" ${Number(state.profile.root)===n?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="detail-actions"><button type="submit" class="btn btn-primary">Enregistrer mes préférences</button></div></form><p class="small muted">La numérotation des octaves suit ici le système international : Do4 = MIDI 60. Le registre sert uniquement aux modèles ; le chant peut se déplacer d’une octave.</p><article class="notice" style="margin-top:20px"><strong>Confidentialité.</strong> Les exercices sonores sont générés sur ton appareil. Cette application n’enregistre pas le micro et n’envoie pas tes réponses. Les fichiers du programme et ton export de pratique sont deux choses distinctes.</article>`}

function staff(notes,root){if(!notes.length)return'';const positions={0:0,1:0,2:1,3:2,4:2,5:3,6:3,7:4,8:5,9:5,10:6,11:6};const width=Math.max(300,notes.length*65+85),bottom=98,step=6,displayRoot=60;return `<svg class="music-staff" viewBox="0 0 ${width} 146" role="img" aria-label="Motif à lire en clef de sol"><text x="14" y="39" fill="currentColor" font-size="12">Clef de sol</text>${[0,1,2,3,4].map(i=>`<line x1="12" y1="${bottom-i*12}" x2="${width-12}" y2="${bottom-i*12}" stroke="currentColor" stroke-width="1"/>`).join('')}${notes.map((note,i)=>{const n=note-root+displayRoot,pc=((n%12)+12)%12,oct=Math.floor(n/12)-5,d=oct*7+positions[pc],y=bottom-(d-2)*step,x=66+i*65;let ledgers='';for(let yy=bottom+12;yy<=y+1;yy+=12)ledgers+=`<line x1="${x-13}" y1="${yy}" x2="${x+13}" y2="${yy}" stroke="currentColor"/>`;for(let yy=bottom-60;yy>=y-1;yy-=12)ledgers+=`<line x1="${x-13}" y1="${yy}" x2="${x+13}" y2="${yy}" stroke="currentColor"/>`;return `${ledgers}<ellipse cx="${x}" cy="${y}" rx="8" ry="5" fill="currentColor" transform="rotate(-18 ${x} ${y})"/><line x1="${x+7}" y1="${y}" x2="${x+7}" y2="${y-34}" stroke="currentColor" stroke-width="1.6"/>`}).join('')}</svg>`}
function piano(root,muted=false){const keys=Array.from({length:13},(_,i)=>root+i);return `<div class="piano" aria-label="Clavier de saisie ${muted?'silencieux':'sonore'}">${keys.map(n=>{const black=[1,3,6,8,10].includes(n%12);return `<button class="piano-key ${black?'black':'white'}" data-action="piano" data-note="${n}" aria-label="${noteName(n)}"><span>${noteName(n)}</span></button>`}).join('')}</div>`}
function workshop(){const p=stageOf(selectedStage);return `${head('Écouter, garder, vérifier','Mon atelier d’écoute','Des modèles sonores synthétisés. Chante librement ; la justesse chantée est autoévaluée.')}<div class="filters"><label class="field grow">Support du palier<select id="workStage">${stageOptions(selectedStage)}</select></label>${btn('new-question','Nouvel essai','','btn-primary')}${btn('stop-audio','Arrêter le son')}</div><div class="notice small"><strong>Support du palier ${p.id} :</strong> ${esc(p.focus)} Les exercices de l’atelier démarrent sur une version simple du palier. Les sous-étapes et les enchaînements complets se travaillent selon le programme avec le piano ou EarMaster.</div><div id="questionPanel" class="card workshop-panel">${questionView()}</div><div class="grid grid-2"><article class="card"><div class="eyebrow">Cette série</div><h3 id="seriesScore">${seriesSummary()}</h3><p class="small">Les réponses de direction sont corrigées automatiquement. Les reproductions chantées restent déclarées par toi. Ces résultats ne valident aucun palier automatiquement.</p><div class="detail-actions">${btn('save-series','Consigner cette série')}${btn('reset-series','Effacer la série')}</div></article><article class="card"><div class="eyebrow">Le bon réflexe</div><h3>Une réponse, puis une comparaison</h3><p class="small">Écouter sans lire la solution. Laisser un silence. Répondre. Comparer. Localiser l’écart avant de recommencer. Une réécoute utile reste une aide, inscrite à part.</p></article></div>`}
function seriesSummary(){const valid=workResults.filter(r=>r.stage===selectedStage&&r.result!=='technical');return `${valid.filter(r=>r.result==='correct'&&!r.assisted).length} premières réponses réussies / ${valid.length} essais`}
function questionView(){if(!question)return `<div class="empty"><h3>Un son, puis un petit silence.</h3><p>Choisis ton palier et lance un nouvel essai.</p>${btn('new-question','Commencer une série','','btn-primary')}</div>`;const q=question;return `<div class="eyebrow">${q.mode==='reading'?'Lecture intérieure':q.mode==='harmony'?'Écoute harmonique':q.mode==='create'?'Intention sonore':'Écoute mélodique'}</div><h3>${esc(q.prompt)}</h3>${q.mode==='reading'?staff(q.notes,q.root):''}<div class="detail-actions">${q.mode==='reading'?btn('play-reference','Donner le Do de référence','','btn-primary'):q.mode==='create'?'':btn('play-question',replays?'Réécouter le modèle':'Écouter le modèle','','btn-primary')}${q.mode==='harmony'?btn('play-chord','Écouter l’accord plaqué'):''}${q.mode==='create'?btn('play-input','Écouter mon intention','','btn-primary'):''}${q.mode!=='direction'&&q.mode!=='create'?btn('mark-attempt',q.attempted?'Réponse chantée notée ✓':'J’ai chanté ma réponse',q.attempted?'disabled':''):''}${q.mode!=='direction'&&q.mode!=='create'?btn('reveal','Écouter / voir la correction'):''}</div><div class="auditory-silence">${questionAnswered?'Réponse consignée. Tu peux comparer, puis passer à un nouvel essai.':q.mode==='reading'?'La mélodie complète reste silencieuse jusqu’à la correction.':q.mode==='create'?'Choisis les notes seulement après avoir entendu la phrase dans ta tête.':replays?'Garde maintenant le son intérieurement, puis réponds.':'Le modèle est masqué pour laisser travailler ton oreille.'}</div>${q.mode==='direction'?`<div class="answer-choices">${[['descend','Plus bas ↘'],['pareil','Identique →'],['monte','Plus haut ↗']].map(([a,l])=>btn('direction-answer',l,`data-answer="${a}" ${questionAnswered?'disabled':''}`)).join('')}</div>`:`${q.mode==='keyboard'||q.mode==='create'?`<p class="small">${q.mode==='keyboard'?'Saisie silencieuse avant vérification.':'Note ton intention avant de l’écouter.'} ${btn('clear-input','Effacer la saisie','','btn-secondary btn-sm')}</p>${piano(q.root,q.mode==='keyboard')}<p class="motif-notes" id="keyboardNotes">${keyboardInput.map(noteName).join(' · ')||'Aucune note saisie'}</p>${q.mode==='keyboard'?btn('check-keyboard','Vérifier ma proposition'):''}`:''}<div class="detail-actions self-rating">${btn('self-correct','Reproduction exacte',`${questionAnswered?'disabled':''}`,'btn-green')}${btn('self-retry','À reprendre',`${questionAnswered?'disabled':''}`)}${btn('self-technical','Retour incertain / technique',`${questionAnswered?'disabled':''}`)}</div>`}<div id="workFeedback" role="status" class="small"></div><p class="small muted">${replays} écoute${replays>1?'s':''} du modèle · hauteur de départ disponible · aucun micro actif.</p>`}
function renderQuestion(){if($('#questionPanel'))$('#questionPanel').innerHTML=questionView();if($('#seriesScore'))$('#seriesScore').textContent=seriesSummary()}
function newQuestion(){stopAudio();const root=Number(state.profile.root)+(selectedStage===22?7:0);question=makeQuestion(selectedStage,root);questionAnswered=false;keyboardInput=[];replays=0;renderQuestion()}
function addWorkResult(result,source='self'){if(questionAnswered)return;workResults.push({stage:selectedStage,result,source,assisted:replays>1||question?.revealed===true||(replays===0&&!['reading','create'].includes(question?.mode)),at:Date.now()});questionAnswered=true;renderQuestion()}
function parseNotes(text){const map={do:0,re:2,mi:4,fa:5,sol:7,la:9,si:11,c:0,d:2,e:4,f:5,g:7,a:9,b:11};return text.trim().split(/[\s,;–-]+/).filter(Boolean).map(token=>{const t=token.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replaceAll('♭','b').replaceAll('♯','#');const m=t.match(/^(do|re|mi|fa|sol|la|si|[a-g])([#b]?)(\d?)$/);if(!m)throw Error('Note non reconnue : '+token);return(m[3]?(Number(m[3])+1)*12:Number(state.profile.root))+map[m[1]]+(m[2]==='#'?1:m[2]==='b'?-1:0)})}

function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},1000)}
function exportJSON(){download(JSON.stringify(state,null,2),`ecoute-interieure-${today()}.json`,'application/json');toast('Sauvegarde JSON préparée')}
function exportCSV(){const rows=[['Date','Palier','Séance','Type','Terminée','Minutes','Essais','Hauteurs première réponse','Rythme première réponse','Après aide','Nouveau','Technique','Confiance','Tonalité','Difficulté','Réussite','Notes'],...state.records.map(r=>[r.date,r.stage,r.title,r.kind,r.done?'Oui':'Non',r.minutes,r.trials,r.pitch,r.rhythm,r.assisted,r.novel?'Oui':'Non',r.technical?'Oui':'Non',r.confidence,r.key,r.difficulty,r.win,r.notes])];download(csv(rows),`ecoute-interieure-seances-${today()}.csv`,'text/csv;charset=utf-8')}
function updateTimer(){const t=state.timer,seconds=timerSeconds(t),clock=$('#timerClock');if(clock)clock.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if($('#timerToggle'))$('#timerToggle').textContent=t?.running?'Pause':seconds?'Reprendre':'Démarrer';if($('#timerContext'))$('#timerContext').textContent=t?`Palier ${t.stage} · ${t.running?'en cours':'en pause'}`:'Le temps sera consigné à la fin.';if(t?.running&&seconds>=900&&!timerNotice){timerNotice=true;toast('15 minutes : tu peux terminer et garder une trace.')}}
function pauseTimer(){if(state.timer){state.timer.elapsed=timerSeconds(state.timer);state.timer.running=false;state.timer.startedAt=null;save()}}
function render(){updateSide();$('#topTitle').textContent=routes[route][0];$('#nav').innerHTML=Object.entries(routes).map(([id,[label,sub]])=>`<button class="nav-btn ${route===id?'active':''}" data-action="route" data-route="${id}" ${route===id?'aria-current="page"':''}><span class="nav-copy"><strong>${label}</strong><small>${sub}</small></span></button>`).join('');$('#content').innerHTML=(storageError?'<div class="notice gold">La sauvegarde locale n’a pas pu être chargée ou écrite. Conserve un export JSON de ta pratique.</div>':'')+({dashboard,program,session,workshop,history:historyPage,journal,vocabulary,keys,assessment,resources,data:dataPage}[route])();updateTimer()}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{
 if(a==='route')go(b.dataset.route);
 else if(a==='close-dialog')closeDialog();
 else if(a==='export')exportJSON();
 else if(a==='export-csv')exportCSV();
 else if(a==='start-current'){selectedStage=state.profile.currentStage;selectedSlot='0';go('session')}
 else if(a==='stage-detail')stageDetail(Number(id));
 else if(a==='edit-stage')editStage(Number(id));
 else if(a==='reset-stage'){if(confirm('Restaurer le contenu initial de ce palier ? Tes séances et notes seront conservées.')){delete state.stageOverrides[id];save();closeDialog();render()}}
 else if(a==='select-stage'){state.profile.currentStage=Number(id);selectedStage=Number(id);selectedSlot='0';save();closeDialog();go('session')}
 else if(a==='phase-filter'){filters.phase=id;go('program')}
 else if(a==='choose-slot'){selectedSlot=b.dataset.slot;render()}
 else if(a==='edit-plan')editPlan();
 else if(a==='add-plan')editPlan(true);
 else if(a==='delete-plan'){if(confirm('Supprimer ce modèle optionnel ? Son historique sera conservé.')){state.extraPlans=state.extraPlans.filter(x=>x.id!==id);if(selectedSlot==='extra:'+id)selectedSlot='0';save();render()}}
 else if(a==='record-plan'){pauseTimer();recordForm()}
 else if(a==='free-session')recordForm(null,true);
 else if(a==='edit-record')recordForm(state.records.find(x=>x.id===id));
 else if(a==='delete-record'){if(confirm('Supprimer cette séance et retirer ses minutes du total ?')){state.records=state.records.filter(x=>x.id!==id);save();render()}}
 else if(a==='timer-toggle'){
  if(state.timer?.running)pauseTimer();else{if(state.timer&&(state.timer.stage!==selectedStage||state.timer.slot!==selectedSlot)){if(!confirm('Remplacer le chronomètre d’une autre séance ? Consigne-la d’abord si tu veux conserver ce temps.'))return;state.timer=null}state.timer={stage:selectedStage,slot:selectedSlot,elapsed:state.timer?.elapsed||0,running:true,startedAt:Date.now()};save()}updateTimer();
 }
 else if(a==='timer-reset'){if(!state.timer||confirm('Remettre le chronomètre à zéro ?')){state.timer=null;timerNotice=false;save();updateTimer()}}
 else if(a==='edit-journal')editJournal(id);
 else if(a==='edit-vocab')editVocab(id);
 else if(a==='edit-key')editKey(b.dataset.key);
 else if(['delete-journal','delete-vocab','delete-assessment'].includes(a)){if(confirm('Supprimer cette entrée ?')){const key={'delete-journal':'journal','delete-vocab':'vocabulary','delete-assessment':'assessments'}[a];state[key]=state[key].filter(x=>x.id!==id);save();render()}}
 else if(a==='play-vocab'){const v=state.vocabulary.find(x=>x.id===id);await playNotes(parseNotes(v.notes),{tempo:state.profile.tempo})}
 else if(a==='workshop-stage'){selectedStage=Number(id);question=null;go('workshop');newQuestion()}
 else if(a==='new-question')newQuestion();
 else if(a==='stop-audio')stopAudio();
 else if(a==='play-reference'){await playNotes([question.root],{tempo:state.profile.tempo});toast('Do de référence donné ; la mélodie reste à entendre intérieurement.')}
 else if(a==='play-question'){if(!question)return;replays++;renderQuestion();await playNotes(question.notes,{tempo:state.profile.tempo,durations:question.durations,gap:question.stage===2?.8:.15})}
 else if(a==='play-chord'){if(!question)return;replays++;renderQuestion();await playNotes(question.notes,{tempo:state.profile.tempo,chord:true})}
 else if(a==='mark-attempt'){if(!question)return;question.attempted=true;renderQuestion()}
 else if(a==='reveal'){if(!question)return;if(!questionAnswered&&!question.attempted)question.revealed=true;await playNotes(question.notes,{tempo:state.profile.tempo,durations:question.durations});$('#workFeedback').textContent='Correction : '+question.notes.map(noteName).join(' · ');}
 else if(a==='direction-answer'){if(!replays)return toast('Écoute d’abord le modèle.');const correct=b.dataset.answer===question.answer;addWorkResult(correct?'correct':'retry','automatic');$('#workFeedback').textContent=(correct?'Exact. ':'À reprendre. ')+'La deuxième note '+(question.answer==='pareil'?'est identique.':question.answer==='monte'?'est plus haute.':'est plus basse.')}
 else if(a==='self-correct'){if(!question)return;if(question.mode==='create'&&!keyboardInput.length)return toast('Note d’abord ton intention sur le clavier.');if(!replays&&question.mode!=='reading'&&question.mode!=='create')return toast('Écoute d’abord le modèle.');addWorkResult('correct')}
 else if(a==='self-retry')addWorkResult('retry');
 else if(a==='self-technical')addWorkResult('technical');
 else if(a==='piano'){keyboardInput.push(Number(b.dataset.note));if($('#keyboardNotes'))$('#keyboardNotes').textContent=keyboardInput.map(noteName).join(' · ');if(question?.mode!=='keyboard'&&question?.mode!=='create')await playNotes([Number(b.dataset.note)],{tempo:120})}
 else if(a==='clear-input'){keyboardInput=[];if($('#keyboardNotes'))$('#keyboardNotes').textContent='Aucune note saisie'}
 else if(a==='play-input'){if(!keyboardInput.length)return toast('Choisis d’abord les notes de ton intention.');await playNotes(keyboardInput,{tempo:state.profile.tempo})}
 else if(a==='check-keyboard'){if(!keyboardInput.length)return toast('Saisis d’abord ta proposition.');const correct=keyboardInput.length===question.notes.length&&keyboardInput.every((n,i)=>n===question.notes[i]);addWorkResult(correct?'correct':'retry','automatic');$('#workFeedback').textContent=correct?'La proposition correspond au modèle.':'À reprendre : écoute la correction et repère la première différence.'}
 else if(a==='reset-series'){workResults=[];question=null;render()}
 else if(a==='save-series'){const rows=workResults.filter(r=>r.stage===selectedStage&&r.result!=='technical');if(!rows.length)return toast('Termine quelques essais avant de consigner la série.');const first=rows.filter(r=>!r.assisted);recordForm(null,true);const form=$('form[data-form="record"]');form.dataset.series='true';form.elements.title.value='Atelier d’écoute · palier '+selectedStage;form.elements.trials.value=Math.max(1,first.length);form.elements.pitch.value=first.length?first.filter(r=>r.result==='correct').length:'';form.elements.novel.checked=first.length>0;form.elements.notes.value=`${rows.length} essais dans l’atelier ; ${rows.filter(r=>r.assisted).length} avec aide. ${rows.some(r=>r.source==='self')?'Justesse chantée autoévaluée.':'Direction ou saisie corrigée automatiquement.'}`;}
 else if(a==='import'){
  const file=$('#importFile').files[0];if(!file)return toast('Choisis une sauvegarde JSON.');if(file.size>10*1024*1024)throw Error('Ce fichier dépasse 10 Mo.');const incoming=importState(JSON.parse(await file.text()));const mode=$('#importMode').value;if(!confirm(mode==='replace'?'Remplacer toutes les données par cette sauvegarde ? Exporte d’abord tes données actuelles si nécessaire.':'Fusionner les données de ce fichier avec ta pratique actuelle ?'))return;state=mode==='replace'?incoming:mergeStates(state,incoming);selectedStage=state.profile.currentStage;selectedSlot='0';save();render();toast('Sauvegarde importée. Les identifiants existants ne sont pas dupliqués.');
 }
}catch(err){console.error(err);toast(err.message||'Cette action n’a pas pu aboutir.')}});

document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const fd=new FormData(f),v=Object.fromEntries(fd),kind=f.dataset.form;try{
 if(kind==='stage-status'){const id=Number(f.dataset.id);state.stageStatus[id]=v.status;state.stageNotes[id]=v.notes;}
 else if(kind==='edit-stage'){state.stageOverrides[f.dataset.id]={title:v.title,focus:v.focus,exercise:v.exercise,criterion:v.criterion,transfer:v.transfer};}
 else if(kind==='plan'){const plan={stage:selectedStage,title:v.title,duration:Number(v.duration),objective:v.objective,instructions:v.instructions,optional:fd.has('optional')};if(f.dataset.new==='true'){const id=uid();state.extraPlans.push({...plan,id,optional:true});selectedSlot='extra:'+id}else if(selectedSlot.startsWith('extra:')){const i=state.extraPlans.findIndex(x=>x.id===selectedSlot.slice(6));state.extraPlans[i]={...state.extraPlans[i],...plan}}else state.plans[selectedStage+'-'+selectedSlot]=plan;}
 else if(kind==='record'){
  const r=normalizeRecord({...v,id:f.dataset.id||uid(),slot:f.dataset.slot,kind:f.dataset.kind,novel:fd.has('novel'),technical:fd.has('technical'),done:fd.has('done'),difficulty:Number(v.difficulty)});if(f.dataset.series==='true')workResults=[];const i=state.records.findIndex(x=>x.id===r.id);if(i>=0)state.records[i]=r;else state.records.push(r);if(statusOf(r.stage)==='todo')state.stageStatus[r.stage]='doing';if(state.timer?.stage===r.stage&&state.timer?.slot===r.slot){state.timer=null;timerNotice=false;}
 }
 else if(kind==='journal'){const j={...v,id:f.dataset.id||uid(),stage:Number(v.stage)};const i=state.journal.findIndex(x=>x.id===j.id);if(i>=0)state.journal[i]=j;else state.journal.push(j);}
 else if(kind==='vocab'){parseNotes(v.notes);const x={...v,id:f.dataset.id||uid(),level:Number(v.level),date:today()};const i=state.vocabulary.findIndex(o=>o.id===x.id);if(i>=0)state.vocabulary[i]=x;else state.vocabulary.push(x);}
 else if(kind==='key'){state.keys[f.dataset.key]={...v,major:Number(v.major),minor:Number(v.minor)};}
 else if(kind==='assessment'){state.assessments.push({id:uid(),date:today(),scores:OBJECTIVES.map((_,i)=>Number(v['score'+i])),comment:v.comment});}
 else if(kind==='settings'){state.profile={...state.profile,name:v.name,weeklyTarget:Number(v.weeklyTarget),defaultDuration:Number(v.defaultDuration),startDate:v.startDate,tempo:Number(v.tempo),root:Number(v.root)};}
 save();if($('#dialog').open)closeDialog();render();toast('Enregistré');
}catch(err){console.error(err);toast(err.message||'Vérifie les informations saisies.')}});

document.addEventListener('change',e=>{if(e.target.id==='phaseFilter'){filters.phase=e.target.value;render()}if(e.target.id==='statusFilter'){filters.status=e.target.value;render()}if(e.target.id==='historyKind'){historyKind=e.target.value;render()}if(e.target.id==='guidedStage'){selectedStage=Number(e.target.value);selectedSlot='0';render()}if(e.target.id==='guidedSlot'){selectedSlot=e.target.value;render()}if(e.target.id==='workStage'){selectedStage=Number(e.target.value);question=null;render();newQuestion()}});
let searchTimeout;document.addEventListener('input',e=>{if(!['programSearch','historySearch'].includes(e.target.id))return;const id=e.target.id,value=e.target.value,pos=e.target.selectionStart;clearTimeout(searchTimeout);searchTimeout=setTimeout(()=>{if(id==='programSearch')filters.query=value;else historySearch=value;render();$('#'+id)?.focus();$('#'+id)?.setSelectionRange(pos,pos)},220)});
$('#theme').addEventListener('click',()=>{state.profile.theme=state.profile.theme==='dark'?'light':'dark';save();render()});
$('#menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
window.addEventListener('hashchange',()=>{route=Object.hasOwn(routes,location.hash.slice(1))?location.hash.slice(1):'dashboard';render()});
window.addEventListener('storage',e=>{if(e.key===STORE_KEY&&e.newValue){try{state=importState(JSON.parse(e.newValue));render();toast('Pratique actualisée depuis un autre onglet')}catch{toast('Une sauvegarde provenant d’un autre onglet est invalide.')}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio()});
window.addEventListener('pagehide',stopAudio);
setInterval(updateTimer,500);render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
